SELECT
    r.request_id, r.request_no, r.student_id, r.user_id, r.dorm_id, r.specialty,
    r.description, r.reporter_name, r.contact_phone, r.images, r.status, r.attempt_count,
    r.create_by, r.create_time, r.update_by, r.update_time, r.remark,
    d.full_name as dorm_name
FROM dorm_repair_request r
LEFT JOIN dorm_building d ON r.dorm_id = d.dorm_id

     and r.request_no = #{requestNo}
     and r.student_id = #{studentId}
     and r.user_id = #{userId}
     and r.dorm_id = #{dormId}
     and r.specialty = #{specialty}
     and r.description = #{description}
     and r.reporter_name like concat('%', #{reporterName}, '%')
     and r.contact_phone = #{contactPhone}
     and r.images = #{images}
     and r.status = #{status}
     and r.create_time = #{createTime}
     and r.update_time = #{updateTime}



        ORDER BY r.${params.orderByColumn} ${params.isAsc}


        ORDER BY r.create_time DESC

