update dorm_repair_request
request_no = #{requestNo}, student_id = #{studentId}, user_id = #{userId}, dorm_id = #{dormId}, specialty = #{specialty}, description = #{description}, reporter_name = #{reporterName}, contact_phone = #{contactPhone}, images = #{images}, status = #{status}, attempt_count = #{attemptCount}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where request_id = #{requestId}
